/*
 * badr-ai-app.js — ONE Cloudflare Worker that serves the whole BADR panel
 * together with the free AI. Same origin, so there is nothing to configure:
 * no endpoint field, no token, no CORS, no key.
 *
 * ── Deploy (about 2 minutes) ────────────────────────────────────────────
 *  1. Cloudflare dashboard → Workers & Pages → Create → Worker → Deploy
 *  2. Edit code → select all → delete → paste this entire file → Deploy
 *  3. Worker → Settings → Bindings → Add → Workers AI
 *        Variable name:  AI
 *  4. Open the worker address. The panel loads with the AI already wired.
 *
 *  The chat lives at  <worker>/            (the panel)
 *                 GET  <worker>/api/health
 *                 GET  <worker>/api/models
 *                 POST <worker>/api/chat   { messages, model }
 *
 *  Six free models, all on the Workers AI allowance:
 *    Llama 3.3 70B · GPT-OSS 120B · Qwen 2.5 Coder 32B
 *    DeepSeek R1 32B · Mistral Small 3.1 24B · Llama 3.1 8B
 *
 *  Optional: set a secret BADR_KEY and every /api call must carry
 *  x-badr-key: <that value>. Skip it if the address stays private.
 *
 *  Note on GPT-4 / Claude: not on the free tier. Workers AI runs
 *  open-weight models only; GPT-OSS 120B is the OpenAI-family one.
 */

// The whole panel, inlined. Served at / and /panel.
const PANEL = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#05070c\">\n<title>BADR LIVE EARTH — UI v1.5</title>\n<style>\n/* badr-ui.css v1.2 — inlined so this file is fully standalone */\n/* ============================================================\n   BADR LIVE EARTH — UI SYSTEM v1\n   One layout, reflows for phone and desktop. Nothing overlaps.\n   States: ON = neon green · OFF = dark+silver · ERR = yellow\n   Alerts = red, always on.\n   ============================================================ */\n\n:root{\n  --bg:#05070c;\n  --bg2:#080b12;\n  --panel:#0b0f18;\n  --panel2:#0e131e;\n  --line:rgba(255,255,255,.10);\n  --line2:rgba(255,255,255,.18);\n  --txt:#eef3fa;\n  --txt2:#b9c3d3;\n  --txt3:#788394;\n\n  --on:#39ff88;\n  --on-bg:rgba(57,255,136,.12);\n  --on-glow:0 0 0 1px rgba(57,255,136,.55), 0 0 18px rgba(57,255,136,.28);\n\n  --off:#aeb6c6;\n  --warn:#ffd400;\n  --warn-bg:rgba(255,212,0,.12);\n  --warn-glow:0 0 0 1px rgba(255,212,0,.5), 0 0 18px rgba(255,212,0,.18);\n\n  --alert:#ff2d55;\n  --alert-bg:rgba(255,45,85,.10);\n  --gold:#ffd700;\n  --cyan:#63e6ff;\n\n  --r:14px;\n  --r-sm:10px;\n  --h-btn:38px;\n  --hdr-h:56px;\n  --safe-b:env(safe-area-inset-bottom,0px);\n  --safe-t:env(safe-area-inset-top,0px);\n}\n\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nhtml,body{height:100%}\nbody{\n  background:radial-gradient(1200px 700px at 50% -10%,#0d1424 0%,var(--bg) 60%) fixed;\n  color:var(--txt);\n  font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;\n  -webkit-font-smoothing:antialiased;\n  overflow:hidden;\n}\nbutton,input,select{font:inherit;color:inherit}\nbutton{cursor:pointer;border:0;background:none}\nsvg{display:block}\n\n/* ── icon sizing ─────────────────────────────────────────── */\n.ic{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.7;\n    stroke-linecap:round;stroke-linejoin:round;flex:0 0 auto}\n.ic.sm{width:16px;height:16px}\n.ic.lg{width:24px;height:24px}\n\n/* ════════════════════════════════════════════════════════\n   BADR ASSIST — floating AI chat (free tier)\n   ════════════════════════════════════════════════════════ */\n.ai{\n  position:fixed;z-index:90;display:none;flex-direction:column;\n  right:12px;bottom:calc(52px + var(--safe-b) + 12px);\n  width:min(384px,calc(100vw - 24px));\n  height:min(470px,calc(100vh - 130px));\n  background:linear-gradient(180deg,#0b111c,#070a11);\n  border:1px solid var(--line2);border-radius:16px;\n  box-shadow:0 30px 80px rgba(0,0,0,.72),0 0 0 1px rgba(99,230,255,.10);\n  overflow:hidden;\n  transform-origin:100% 100%;\n  animation:aiIn .18s cubic-bezier(.22,1,.36,1);\n}\n@keyframes aiIn{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:none}}\n.ai.open{display:flex}\n\n.ai-h{display:flex;align-items:center;gap:8px;padding:9px 9px 9px 12px;\n      border-bottom:1px solid var(--line);flex:0 0 auto;background:rgba(8,11,18,.9)}\n.ai-h .t{font-size:.64rem;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold)}\n.ai-mark{color:var(--cyan)}\n.ai-st{\n  margin-left:auto;display:inline-flex;align-items:center;gap:5px;flex:0 0 auto;\n  font-size:.54rem;font-weight:900;letter-spacing:.9px;text-transform:uppercase;\n  padding:3px 8px;border-radius:999px;border:1px solid var(--line2);color:var(--txt3);\n}\n.ai-st .dot{width:6px;height:6px}\n.ai-st.on{color:var(--on);border-color:rgba(57,255,136,.45);background:rgba(57,255,136,.10)}\n.ai-st.on .dot{background:var(--on);box-shadow:0 0 8px var(--on)}\n.ai-st.err{color:var(--warn);border-color:rgba(255,212,0,.45);background:rgba(255,212,0,.10)}\n.ai-st.err .dot{background:var(--warn);box-shadow:0 0 8px var(--warn)}\n.ai-st.work{color:var(--cyan);border-color:rgba(99,230,255,.45);background:rgba(99,230,255,.10)}\n.ai-st.work .dot{background:var(--cyan);box-shadow:0 0 8px var(--cyan);animation:pulse 1s ease-in-out infinite}\n\n.ai-x{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;flex:0 0 auto;\n      border:1px solid var(--line2);background:#0b0f18;color:var(--txt2)}\n.ai-x:hover{color:var(--txt);border-color:rgba(255,255,255,.3)}\n.ai-x.on{color:var(--gold);border-color:rgba(255,215,0,.55);background:rgba(255,215,0,.10)}\n\n.ai-cfg{padding:10px 12px;border-bottom:1px solid var(--line);background:#060a11;\n        display:flex;flex-direction:column;gap:8px;flex:0 0 auto}\n.ai-cfg[hidden]{display:none}\n.cfg-row{display:flex;align-items:center;gap:8px}\n.cfg-lbl{flex:0 0 58px;font-size:.54rem;font-weight:900;letter-spacing:1px;text-transform:uppercase;color:var(--txt3)}\n.cfg-row input{\n  flex:1;min-width:0;height:30px;padding:0 9px;border-radius:8px;\n  border:1px solid var(--line2);background:#05080e;color:var(--txt);font-size:.68rem;\n}\n.cfg-row input:focus,.cfg-row select:focus{outline:none;border-color:rgba(99,230,255,.55);box-shadow:0 0 0 3px rgba(99,230,255,.10)}\n.cfg-row select{\n  flex:1;min-width:0;height:30px;padding:0 8px;border-radius:8px;\n  border:1px solid var(--line2);background:#05080e;color:var(--txt);\n  font-size:.64rem;font-weight:700;letter-spacing:.2px;\n  appearance:none;-webkit-appearance:none;\n  background-image:linear-gradient(45deg,transparent 50%,var(--txt3) 50%),linear-gradient(135deg,var(--txt3) 50%,transparent 50%);\n  background-position:calc(100% - 14px) 13px,calc(100% - 9px) 13px;\n  background-size:5px 5px,5px 5px;background-repeat:no-repeat;\n}\n.cfg-row input[type=password]{letter-spacing:1px}\n.go-sm{\n  flex:0 0 auto;height:30px;padding:0 10px;border-radius:8px;\n  border:1px solid rgba(57,255,136,.45);background:rgba(57,255,136,.12);color:var(--on);\n  font-size:.56rem;font-weight:900;letter-spacing:1px;text-transform:uppercase;\n}\n.go-sm:hover{background:rgba(57,255,136,.22)}\n.cfg-row[hidden]{display:none}\n.seg{display:flex;gap:4px}\n.seg button{\n  height:28px;padding:0 10px;border-radius:7px;border:1px solid var(--line2);\n  background:#0a0e16;color:var(--txt3);font-size:.56rem;font-weight:900;letter-spacing:1px;text-transform:uppercase;\n}\n.seg button.on{color:var(--on);border-color:rgba(57,255,136,.5);background:rgba(57,255,136,.12)}\n.cfg-note{font-size:.56rem;line-height:1.65;color:var(--txt3);white-space:pre-line}\n.cfg-note code{background:#0b0f18;border:1px solid var(--line2);border-radius:4px;padding:0 4px;color:var(--cyan)}\n.cfg-note.warn{color:var(--warn)}\n\n.ai-log{flex:1 1 auto;min-height:0;overflow-y:auto;padding:12px;display:flex;flex-direction:column;gap:8px}\n.ai-msg{max-width:93%;padding:8px 10px;border-radius:11px;font-size:.73rem;line-height:1.65;\n        white-space:pre-wrap;overflow-wrap:anywhere}\n.ai-msg.bot{align-self:flex-start;background:#0d1420;border:1px solid var(--line2);color:var(--txt)}\n.ai-msg.me{align-self:flex-end;background:rgba(57,255,136,.13);border:1px solid rgba(57,255,136,.40);color:#dcffec}\n.ai-msg.sys{align-self:stretch;max-width:100%;background:#080c14;border:1px dashed var(--line2);color:var(--txt3);font-size:.65rem}\n.ai-msg.bad{align-self:stretch;max-width:100%;background:rgba(255,212,0,.09);border:1px solid rgba(255,212,0,.45);color:var(--warn);font-size:.65rem}\n.ai-msg.think{color:var(--cyan);font-style:italic}\n\n.ai-in{display:flex;gap:6px;padding:9px 10px;border-top:1px solid var(--line);flex:0 0 auto;background:#070b12}\n.ai-in input{\n  flex:1;min-width:0;height:36px;padding:0 11px;border-radius:10px;\n  border:1px solid var(--line2);background:#05080e;color:var(--txt);font-size:.76rem;\n}\n.ai-in input::placeholder{color:#5c6677}\n.ai-in input:focus{outline:none;border-color:rgba(99,230,255,.55);box-shadow:0 0 0 3px rgba(99,230,255,.10)}\n.ai-in .go{\n  width:36px;height:36px;flex:0 0 auto;border-radius:10px;display:grid;place-items:center;\n  border:1px solid rgba(57,255,136,.45);background:rgba(57,255,136,.12);color:var(--on);\n}\n.ai-in .go:hover{background:rgba(57,255,136,.22)}\n.ai-in .go[disabled]{opacity:.45;cursor:not-allowed}\n\n/* ══════════════════════════════════════════════════════════\n   SHELL\n   ══════════════════════════════════════════════════════════ */\n.app{\n  position:fixed;inset:0;\n  display:grid;\n  grid-template-columns:var(--rail-w,64px) minmax(0,1fr) var(--side-w,330px);\n  grid-template-rows:auto auto minmax(0,1fr) auto;\n  grid-template-areas:\n    \"hdr hdr hdr\"\n    \"alert alert alert\"\n    \"rail map side\"\n    \"dock dock dock\";\n}\n.app.side-closed{--side-w:0px}\n\n/* ── header: never overlaps, never clips ───────────────── */\n.hdr{\n  grid-area:hdr;position:relative;\n  display:grid;\n  grid-template-columns:auto minmax(0,1fr) auto auto;\n  align-items:center;\n  gap:10px;\n  height:var(--hdr-h);\n  padding:0 12px 0 12px;\n  padding-top:var(--safe-t);\n  background:linear-gradient(180deg,rgba(8,11,18,.98),rgba(8,11,18,.86));\n  border-bottom:1px solid var(--line);\n  backdrop-filter:blur(14px);\n  z-index:40;\n}\n.logo,.title-wrap{min-width:0}\n.title-wrap{min-width:0;overflow:hidden}\n.logo{\n  width:32px;height:32px;flex:0 0 auto;border-radius:10px;\n  display:grid;place-items:center;\n  background:linear-gradient(150deg,#0f1a2b,#0a0e16);\n  border:1px solid rgba(255,215,0,.42);\n  box-shadow:0 0 16px rgba(255,215,0,.12), inset 0 1px 0 rgba(255,255,255,.06);\n  color:var(--gold);\n}\n.title{\n  min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;\n  font-size:.82rem;font-weight:800;letter-spacing:1.6px;\n  color:var(--txt);\n}\n.title b{color:var(--gold);font-weight:800}\n.sub{\n  display:block;font-size:.52rem;letter-spacing:1.4px;color:var(--txt3);\n  font-weight:700;margin-top:1px;overflow:hidden;text-overflow:ellipsis;\n}\n\n/* the 4 map buttons — their own track, never squeezed, never overlapped */\n.maps{display:flex;gap:6px;flex:0 0 auto;align-items:center;justify-self:end}\n\n/* ── ALERT PILL — lives in the header's own last column.\n      It is NOT inside .maps, so no map button can ever cover it,\n      and no map button can ever be covered by it. ───────────── */\n.alertpill{\n  grid-column:4;justify-self:end;flex:0 0 auto;\n  height:34px;padding:0 10px;gap:7px;border-radius:10px;\n  font-size:.62rem;font-weight:900;letter-spacing:1.3px;\n  color:#fff;\n  background:linear-gradient(180deg,rgba(255,45,85,.42),rgba(255,45,85,.20));\n  border:1px solid rgba(255,45,85,.85);\n  box-shadow:0 0 0 1px rgba(255,45,85,.25),0 0 18px rgba(255,45,85,.30);\n  animation:alertPulse 2.6s ease-in-out infinite;\n}\n.alertpill:hover{background:linear-gradient(180deg,rgba(255,45,85,.58),rgba(255,45,85,.30))}\n.alertpill .ap-t{color:#fff;letter-spacing:1.5px}\n/* hard guards: the pill may never be clipped, shrunk or stacked under anything */\n.hdr{overflow:visible}\n.hdr > .alertpill{position:relative;z-index:6}\n.hdr > .maps{position:relative;z-index:5}\n.alertpill .count{background:rgba(255,255,255,.22);color:#fff}\n@keyframes alertPulse{\n  0%,100%{box-shadow:0 0 0 1px rgba(255,45,85,.25),0 0 18px rgba(255,45,85,.28)}\n  50%    {box-shadow:0 0 0 1px rgba(255,45,85,.45),0 0 26px rgba(255,45,85,.48)}\n}\n@media (max-width:1180px){ .alertpill .ap-t{display:none} }\n\n/* ── buttons ───────────────────────────────────────────── */\n.btn{\n  position:relative;\n  display:inline-flex;align-items:center;justify-content:center;gap:7px;\n  height:var(--h-btn);min-width:var(--h-btn);padding:0 12px;\n  border-radius:var(--r-sm);\n  border:1px solid var(--line2);\n  background:linear-gradient(180deg,#111826,#0b0f18);\n  color:var(--txt);\n  font-size:.7rem;font-weight:800;letter-spacing:.9px;text-transform:uppercase;\n  white-space:nowrap;\n  transition:border-color .16s,color .16s,box-shadow .16s,background .16s,transform .08s;\n}\n.btn:hover{border-color:rgba(255,255,255,.30);background:linear-gradient(180deg,#16202f,#0d1220)}\n.btn:active{transform:translateY(1px)}\n.btn.icon{padding:0;width:var(--h-btn)}\n.btn.icon .lbl-txt{display:none}\n.btn.locked{cursor:default}\n\n/* ON — neon green */\n.btn.on{\n  color:var(--on);border-color:rgba(57,255,136,.55);\n  background:linear-gradient(180deg,rgba(57,255,136,.16),rgba(57,255,136,.06));\n  box-shadow:var(--on-glow);\n}\n/* OFF — dark, silver */\n.btn.off{color:var(--off);border-color:var(--line);background:linear-gradient(180deg,#0b1019,#080c14)}\n.btn.off:hover{color:var(--txt2)}\n/* ERROR / DOWN / UNDER CONSTRUCTION — yellow on dark */\n.btn.err{\n  color:var(--warn);border-color:rgba(255,212,0,.5);\n  background:linear-gradient(180deg,rgba(255,212,0,.10),rgba(255,212,0,.03));\n  box-shadow:var(--warn-glow);\n}\n/* ALERT — red, always visible */\n.btn.alert{\n  color:#fff;border-color:rgba(255,45,85,.75);\n  background:linear-gradient(180deg,rgba(255,45,85,.34),rgba(255,45,85,.16));\n  box-shadow:0 0 0 1px rgba(255,45,85,.35),0 0 22px rgba(255,45,85,.22);\n}\n.btn.alert .dot{background:var(--alert);box-shadow:0 0 10px var(--alert)}\n\n.dot{width:7px;height:7px;border-radius:50%;background:currentColor;flex:0 0 auto}\n.dot.live{animation:pulse 1.6s ease-in-out infinite}\n@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.72)}}\n\n.count{\n  min-width:18px;height:16px;padding:0 5px;border-radius:5px;\n  display:inline-grid;place-items:center;\n  font-size:.6rem;font-weight:900;letter-spacing:0;\n  background:rgba(255,255,255,.10);color:var(--txt);\n}\n.btn.on .count{background:rgba(57,255,136,.22);color:var(--on)}\n.btn.err .count{background:rgba(255,212,0,.20);color:var(--warn)}\n\n/* ── alert bar: always on, wide, dark red ──────────────── */\n.alertbar{\n  grid-area:alert;\n  display:flex;align-items:center;gap:9px;\n  height:30px;padding:0 12px;\n  background:linear-gradient(90deg,rgba(255,45,85,.16),rgba(255,45,85,.06) 55%,rgba(255,45,85,.12));\n  border-bottom:1px solid rgba(255,45,85,.30);\n  color:#ffd9e2;font-size:.66rem;font-weight:700;letter-spacing:.5px;\n  overflow:hidden;white-space:nowrap;z-index:30;\n}\n.alertbar .lbl{\n  display:inline-flex;align-items:center;gap:6px;flex:0 0 auto;\n  color:var(--alert);font-weight:900;letter-spacing:1.4px;font-size:.6rem;text-transform:uppercase;\n}\n.alertbar .txt{overflow:hidden;text-overflow:ellipsis;color:#ffc9d6;min-width:0}\n.alertbar .more{margin-left:auto;flex:0 0 auto;color:#ff9db2;font-size:.6rem;font-weight:800}\n\n/* ══════════════════════════════════════════════════════════\n   LEFT RAIL\n   ══════════════════════════════════════════════════════════ */\n.rail{\n  grid-area:rail;\n  display:flex;flex-direction:column;align-items:center;gap:4px;\n  padding:8px 0;\n  background:rgba(6,9,15,.9);\n  border-right:1px solid var(--line);\n  overflow-y:auto;overflow-x:hidden;\n  scrollbar-width:none;\n  z-index:20;\n}\n.rail::-webkit-scrollbar{display:none}\n.rail .sep{width:26px;height:1px;background:var(--line);margin:5px 0;flex:0 0 auto}\n\n.rbtn{\n  position:relative;\n  width:44px;height:42px;border-radius:11px;\n  display:grid;place-items:center;\n  color:var(--off);\n  border:1px solid transparent;\n  background:transparent;\n  transition:.15s;\n  flex:0 0 auto;\n}\n.rbtn:hover{background:rgba(255,255,255,.06);color:var(--txt)}\n.rbtn .ic{width:21px;height:21px}\n.rbtn.on{\n  color:var(--on);background:var(--on-bg);\n  border-color:rgba(57,255,136,.42);\n  box-shadow:inset 3px 0 0 var(--on);\n}\n.rbtn.err{color:var(--warn);background:var(--warn-bg);border-color:rgba(255,212,0,.38)}\n.rbtn .tip{\n  position:absolute;left:52px;top:50%;transform:translateY(-50%) translateX(-4px);\n  background:#111826;border:1px solid var(--line2);color:var(--txt);\n  padding:5px 9px;border-radius:8px;font-size:.62rem;font-weight:700;letter-spacing:.6px;\n  white-space:nowrap;opacity:0;pointer-events:none;transition:.14s;z-index:60;\n  box-shadow:0 8px 24px rgba(0,0,0,.5);\n}\n.rbtn:hover .tip{opacity:1;transform:translateY(-50%) translateX(0)}\n.rail .grow{flex:1 1 auto;min-height:6px}\n\n/* ══════════════════════════════════════════════════════════\n   MAP STAGE\n   ══════════════════════════════════════════════════════════ */\n.stage{\n  grid-area:map;position:relative;min-width:0;min-height:0;\n  background:\n    radial-gradient(900px 520px at 30% 20%,rgba(24,40,70,.55),transparent 70%),\n    radial-gradient(700px 460px at 80% 75%,rgba(60,20,50,.35),transparent 70%),\n    #04060b;\n  overflow:hidden;\n}\n.grid-lines{\n  position:absolute;inset:0;opacity:.16;pointer-events:none;\n  background-image:\n    linear-gradient(rgba(99,230,255,.35) 1px,transparent 1px),\n    linear-gradient(90deg,rgba(99,230,255,.35) 1px,transparent 1px);\n  background-size:64px 64px;\n  mask-image:radial-gradient(circle at 50% 50%,#000 30%,transparent 78%);\n}\n/* 2D flat plane — a rectangle of graticule, never a sphere */\n.plane-ghost{\n  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);\n  width:min(78vh,680px);max-width:86%;aspect-ratio:2/1;border-radius:14px;\n  border:1px solid rgba(99,230,255,.16);\n  background-image:\n    linear-gradient(rgba(99,230,255,.10) 1px,transparent 1px),\n    linear-gradient(90deg,rgba(99,230,255,.10) 1px,transparent 1px);\n  background-size:100% 25%,12.5% 100%;\n  box-shadow:inset 0 0 90px rgba(99,230,255,.05);\n  pointer-events:none;\n}\n.plane-ghost::after{\n  content:\"\";position:absolute;left:0;right:0;top:50%;height:1px;\n  background:rgba(255,215,0,.38);box-shadow:0 0 12px rgba(255,215,0,.25);\n}\n.stage .stamp{\n  position:absolute;left:14px;bottom:14px;\n  font-size:.58rem;letter-spacing:1.6px;color:var(--txt3);font-weight:800;text-transform:uppercase;\n}\n/* master switches — top-LEFT of the map.\n   the top-right corner is left empty on purpose: that is where the\n   alert pill and the 4 map buttons meet, and nothing else may sit there. */\n.mapctl{\n  position:absolute;left:12px;top:12px;display:flex;gap:6px;flex-wrap:wrap;\n  justify-content:flex-start;max-width:calc(100% - 24px);\n}\n\n/* ══════════════════════════════════════════════════════════\n   RIGHT SIDE — OSINT TOOLKIT\n   ══════════════════════════════════════════════════════════ */\n.side{\n  grid-area:side;min-width:0;\n  display:flex;flex-direction:column;gap:0;\n  background:rgba(7,10,17,.96);\n  border-left:1px solid var(--line);\n  overflow:hidden;z-index:20;\n}\n.app.side-closed .side{display:none}\n.app.side-open .side{display:flex}\n\n.side-h{\n  display:flex;align-items:center;gap:8px;\n  padding:10px 12px;border-bottom:1px solid var(--line);\n  flex:0 0 auto;\n}\n.side-h .t{font-size:.64rem;font-weight:900;letter-spacing:1.8px;text-transform:uppercase;color:var(--gold)}\n.side-h .n{margin-left:auto;font-size:.58rem;color:var(--txt3);font-weight:700;letter-spacing:1px}\n.side-b{overflow-y:auto;padding:10px;display:flex;flex-direction:column;gap:10px}\n\n.card{\n  border:1px solid var(--line);border-radius:var(--r);\n  background:linear-gradient(180deg,var(--panel),var(--panel2));\n  padding:11px;\n}\n.card-h{display:flex;align-items:center;gap:7px;margin-bottom:9px}\n.card-h .ic{color:var(--cyan);width:17px;height:17px}\n.card-h .t{font-size:.66rem;font-weight:900;letter-spacing:1.3px;text-transform:uppercase;color:var(--txt)}\n.card-h .s{margin-left:auto;font-size:.56rem;color:var(--txt3);font-weight:700;letter-spacing:.8px}\n\n.field{display:flex;gap:6px}\n.field input{\n  flex:1;min-width:0;height:34px;padding:0 10px;\n  border-radius:9px;border:1px solid var(--line2);\n  background:#05080e;color:var(--txt);\n  font-size:.74rem;letter-spacing:.2px;\n}\n.field input::placeholder{color:#5c6677}\n.field input:focus{outline:none;border-color:rgba(99,230,255,.55);box-shadow:0 0 0 3px rgba(99,230,255,.10)}\n.field .go{\n  height:34px;padding:0 12px;border-radius:9px;\n  border:1px solid rgba(57,255,136,.45);\n  background:rgba(57,255,136,.12);color:var(--on);\n  font-size:.64rem;font-weight:900;letter-spacing:1.2px;text-transform:uppercase;\n  display:inline-flex;align-items:center;gap:5px;\n}\n.field .go:hover{background:rgba(57,255,136,.2)}\n\n.tabs{display:flex;gap:5px;margin-bottom:9px;flex-wrap:wrap}\n.tab{\n  height:26px;padding:0 9px;border-radius:7px;\n  border:1px solid var(--line);background:#0a0e16;color:var(--txt3);\n  font-size:.58rem;font-weight:900;letter-spacing:1.1px;text-transform:uppercase;\n}\n.tab.on{color:var(--gold);border-color:rgba(255,215,0,.45);background:rgba(255,215,0,.10)}\n\n.res{display:flex;flex-direction:column;gap:5px;margin-top:9px}\n.res-i{\n  display:flex;align-items:center;gap:8px;\n  padding:7px 9px;border-radius:9px;\n  background:#070b12;border:1px solid var(--line);\n  font-size:.7rem;color:var(--txt2);\n}\n.res-i b{color:var(--txt);font-weight:700;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.res-i .st{margin-left:auto;font-size:.56rem;font-weight:900;letter-spacing:1px;padding:2px 6px;border-radius:5px}\n.res-i .st.found{color:var(--on);background:rgba(57,255,136,.12)}\n.res-i .st.none{color:var(--txt3);background:rgba(255,255,255,.05)}\n.res-i .st.warn{color:var(--warn);background:rgba(255,212,0,.12)}\n\n/* ══════════════════════════════════════════════════════════\n   BOTTOM DOCK  (3 free slots + status)\n   ══════════════════════════════════════════════════════════ */\n.dock{\n  grid-area:dock;\n  display:flex;align-items:center;gap:8px;\n  height:calc(52px + var(--safe-b));\n  padding:0 10px var(--safe-b);\n  background:linear-gradient(0deg,rgba(7,10,17,.99),rgba(7,10,17,.9));\n  border-top:1px solid var(--line);\n  z-index:30;overflow-x:auto;scrollbar-width:none;\n}\n.dock::-webkit-scrollbar{display:none}\n.dock-scroll{\n  display:flex;align-items:center;gap:8px;\n  flex:1 1 auto;min-width:0;\n  overflow-x:auto;overflow-y:hidden;scrollbar-width:none;\n}\n.dock-scroll::-webkit-scrollbar{display:none}\n.dock-pin{display:flex;align-items:center;gap:8px;flex:0 0 auto}\n.slot.free{border-style:dashed}\n.slot.free:hover{border-color:rgba(255,215,0,.55);color:var(--gold);background:rgba(255,215,0,.06)}\n.ai-trigger{border-color:rgba(99,230,255,.42);color:var(--cyan);background:linear-gradient(180deg,rgba(99,230,255,.14),rgba(99,230,255,.04))}\n.ai-trigger:hover{border-color:rgba(99,230,255,.7);box-shadow:0 0 18px rgba(99,230,255,.22)}\n.ai-trigger.on{border-color:rgba(99,230,255,.8);box-shadow:0 0 0 1px rgba(99,230,255,.35),0 0 20px rgba(99,230,255,.3)}\n.dock .slot{\n  flex:0 0 auto;display:inline-flex;align-items:center;gap:7px;\n  height:34px;padding:0 12px;border-radius:10px;\n  border:1px dashed rgba(255,255,255,.16);\n  color:var(--txt3);font-size:.62rem;font-weight:900;letter-spacing:1.2px;text-transform:uppercase;\n  background:rgba(255,255,255,.02);\n}\n.dock .slot.used{border-style:solid;color:var(--txt2);border-color:var(--line2)}\n.dock .grow{flex:1 1 auto;min-width:8px}\n.dock .clock{\n  flex:0 0 auto;font-variant-numeric:tabular-nums;\n  font-size:.64rem;font-weight:800;letter-spacing:1.2px;color:var(--txt2);\n  padding:0 4px;\n}\n\n/* ══════════════════════════════════════════════════════════\n   MOBILE  ≤ 820px\n   header becomes 2 rows → the 4 map buttons get their own\n   full-width row, so the title can never cover them.\n   ══════════════════════════════════════════════════════════ */\n.mobile-only{display:none}\n\n@media (max-width:820px){\n  .app{\n    --rail-w:0px;--side-w:0px;\n    grid-template-columns:minmax(0,1fr);\n    grid-template-rows:auto auto minmax(0,1fr) auto auto;\n    grid-template-areas:\n      \"hdr\"\n      \"alert\"\n      \"map\"\n      \"rail\"\n      \"dock\";\n  }\n  .hdr{\n    height:auto;\n    padding:calc(8px + var(--safe-t)) 10px 8px;\n    grid-template-columns:auto minmax(0,1fr) auto;\n    row-gap:8px;\n  }\n  .alertpill{grid-area:alerts;height:32px;padding:0 9px}\n  .logo{grid-area:logo}\n  .title-wrap{grid-area:title}\n  .title-wrap .sub{display:none}\n  .title{font-size:.76rem;letter-spacing:1.2px}\n  .maps{\n    grid-area:maps;\n    display:grid;grid-template-columns:repeat(4,1fr);gap:6px;\n    width:100%;\n  }\n  .hdr{grid-template-areas:\"logo title alerts\" \"maps maps maps\"}\n  .maps .btn{width:100%;justify-content:center}\n  .maps .btn .lbl-txt{display:inline}\n\n  /* master switches: one compact row, never a second row over the map */\n  .mapctl{\n    left:8px;right:8px;top:8px;gap:5px;max-width:none;\n    flex-wrap:nowrap;justify-content:flex-start;\n    overflow-x:auto;scrollbar-width:none;\n  }\n  .mapctl::-webkit-scrollbar{display:none}\n  .mapctl .btn{height:31px;padding:0 8px;font-size:.55rem;letter-spacing:.5px;gap:5px;flex:0 0 auto}\n  .mapctl .btn .ic.sm{width:13px;height:13px}\n  .mapctl .btn .count{height:14px;min-width:16px;font-size:.55rem}\n\n  /* left rail turns into a horizontal strip under the map */\n  .rail{\n    flex-direction:row;align-items:center;\n    gap:5px;padding:6px 8px;\n    border-right:0;border-top:1px solid var(--line);\n    overflow-x:auto;overflow-y:hidden;\n  }\n  .rail{scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch}\n  .rail .sep{width:1px;height:24px;margin:0 3px;flex:0 0 auto}\n  .rbtn{width:38px;height:36px;scroll-snap-align:start}\n  .rbtn .ic{width:19px;height:19px}\n  .rbtn .tip{display:none}\n  .rail .grow{display:none}\n\n  /* side panel becomes a slide-over sheet */\n  .side{\n    position:fixed;inset:auto 0 0 0;top:0;\n    max-width:none;width:min(92vw,380px);margin-left:auto;\n    transform:translateX(103%);visibility:hidden;\n    transition:transform .26s cubic-bezier(.22,1,.36,1),visibility .26s;\n    z-index:80;border-left:1px solid var(--line2);\n    box-shadow:-30px 0 60px rgba(0,0,0,.6);\n  }\n  .app.side-open .side{transform:none;visibility:visible}\n\n  .stage .stamp{\n    font-size:.48rem;letter-spacing:.8px;left:10px;bottom:10px;\n    white-space:nowrap;max-width:calc(100% - 20px);overflow:hidden;text-overflow:ellipsis;\n  }\n  .plane-ghost{max-width:92%}\n\n  /* assist becomes a bottom sheet */\n  .ai{\n    right:0;left:0;bottom:0;width:auto;\n    height:min(74vh,560px);\n    border-radius:16px 16px 0 0;border-bottom:0;\n    transform-origin:50% 100%;\n    animation:aiSheet .22s cubic-bezier(.22,1,.36,1);\n  }\n  @keyframes aiSheet{from{transform:translateY(100%)}to{transform:none}}\n\n  /* dock: labels drop, icons only -> everything fits, nothing is clipped */\n  .dock{height:calc(50px + var(--safe-b));gap:6px;padding:0 8px var(--safe-b)}\n  .slot-t{display:none}\n  .dock .slot{height:34px;width:38px;padding:0;justify-content:center;gap:0}\n  .dock-pin{gap:6px}\n  .dock-pin .clock{font-size:.55rem;letter-spacing:.5px;padding:0}\n  .app.side-closed .side{display:flex;transform:translateX(103%);visibility:hidden}\n  .sheet-x{display:grid}\n  .mobile-only{display:inline-flex}\n  .dock{height:calc(50px + var(--safe-b))}\n}\n@media (min-width:821px){\n  .app.side-closed .side{display:none}\n  .sheet-x{display:none}\n}\n\n/* scrim for the mobile sheet */\n.scrim{\n  position:fixed;inset:0;background:rgba(0,0,0,.6);backdrop-filter:blur(3px);\n  opacity:0;pointer-events:none;transition:.2s;z-index:70;\n}\n.app.side-open ~ .scrim,.scrim.on{opacity:1;pointer-events:auto}\n\n.sheet-x{\n  width:30px;height:30px;border-radius:8px;place-items:center;\n  border:1px solid var(--line2);color:var(--txt2);background:#0b0f18;\n  margin-left:auto;\n}\n\n</style>\n</head>\n<body>\n\n<!-- ══════════════════════════════════════════════════════════\n     ICON SPRITE — all new, drawn for this shell\n     ══════════════════════════════════════════════════════════ -->\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <symbol id=\"i-logo\" viewBox=\"0 0 24 24\">\n      <circle cx=\"12\" cy=\"12\" r=\"9\"/><ellipse cx=\"12\" cy=\"12\" rx=\"4\" ry=\"9\"/>\n      <path d=\"M3.4 9h17.2M3.4 15h17.2\"/><circle cx=\"12\" cy=\"12\" r=\"2.2\" fill=\"currentColor\" stroke=\"none\"/>\n    </symbol>\n    <symbol id=\"i-layers\" viewBox=\"0 0 24 24\"><path d=\"M12 3 3 8l9 5 9-5-9-5Z\"/><path d=\"m3 12 9 5 9-5\"/><path d=\"m3 16 9 5 9-5\"/></symbol>\n    <symbol id=\"i-search\" viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.6-3.6\"/></symbol>\n    <symbol id=\"i-alert\" viewBox=\"0 0 24 24\"><path d=\"M12 3.5 2.8 20h18.4L12 3.5Z\"/><path d=\"M12 9.5v4.5\"/><circle cx=\"12\" cy=\"17.2\" r=\".9\" fill=\"currentColor\" stroke=\"none\"/></symbol>\n    <symbol id=\"i-flat\" viewBox=\"0 0 24 24\"><rect x=\"2.5\" y=\"5\" width=\"19\" height=\"14\" rx=\"2\"/><path d=\"M2.5 12h19M8 5v14M16 5v14\"/></symbol>\n    <symbol id=\"i-expand\" viewBox=\"0 0 24 24\"><path d=\"M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5\"/></symbol>\n    <symbol id=\"i-sat\" viewBox=\"0 0 24 24\"><rect x=\"9.2\" y=\"9.2\" width=\"5.6\" height=\"5.6\" rx=\"1\" transform=\"rotate(45 12 12)\"/><path d=\"m7 7-3-3M17 17l3 3M6.4 10.8 3.5 13.7M13.2 17.6l-2.9 2.9\"/><path d=\"M9.5 4.2 4.2 9.5M14.5 19.8l5.3-5.3\"/></symbol>\n    <symbol id=\"i-plane\" viewBox=\"0 0 24 24\"><path d=\"M10.2 3.6c.5-1 2-1 2.5 0l1.1 6.1 6.4 3.5v2.2l-6.4-1.8-.9 4 2.4 1.9V21l-3.6-1.2L7.7 21v-1.5l2.4-1.9-.9-4L2.8 15.4v-2.2l6.4-3.5 1-6.1Z\"/></symbol>\n    <symbol id=\"i-ship\" viewBox=\"0 0 24 24\"><path d=\"M4 16.5h16l-2 3.2H6l-2-3.2Z\"/><path d=\"M6.2 16.5V11h11.6v5.5\"/><path d=\"M12 11V5.5M9 8h6\"/></symbol>\n    <symbol id=\"i-balloon\" viewBox=\"0 0 24 24\"><path d=\"M12 3a5.6 5.6 0 0 1 5.6 5.6c0 3.9-3.1 6.2-5.6 6.9-2.5-.7-5.6-3-5.6-6.9A5.6 5.6 0 0 1 12 3Z\"/><path d=\"M12 15.5V21\"/><path d=\"m10.4 17.6 1.6 1.3 1.6-1.3\"/></symbol>\n    <symbol id=\"i-cctv\" viewBox=\"0 0 24 24\"><path d=\"m3 9.2 11.6-3.4 1.8 6.1L4.8 15.3 3 9.2Z\"/><path d=\"M4.8 15.3 4 18.6h4.4l.8-2.7\"/><path d=\"M9.2 13.1 7.4 7\"/><circle cx=\"17.8\" cy=\"14.6\" r=\"2.4\"/></symbol>\n    <symbol id=\"i-fire\" viewBox=\"0 0 24 24\"><path d=\"M12 21c3.4 0 6-2.4 6-5.6 0-4.4-4.3-6.3-4-11.4-2.9 1.3-4.6 4-4.6 6.3 0 1.3.5 2.2 1.2 2.9-1.5-.2-2.5-1-3.1-2.2-.9 1.3-1.5 2.8-1.5 4.4C6 18.6 8.6 21 12 21Z\"/></symbol>\n    <symbol id=\"i-quake\" viewBox=\"0 0 24 24\"><path d=\"M2 13h3.2l1.8-6 2.6 12 2.6-9 2 6 1.6-3H22\"/></symbol>\n    <symbol id=\"i-cloud\" viewBox=\"0 0 24 24\"><path d=\"M7 18.5h9.5a4 4 0 0 0 .4-8 5.5 5.5 0 0 0-10.5 1.4A3.3 3.3 0 0 0 7 18.5Z\"/></symbol>\n    <symbol id=\"i-rad\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"2.1\"/><path d=\"M12 9.9V3.4a8.6 8.6 0 0 1 4.3 1.2l-3.2 5.5\"/><path d=\"M10 12.5 4.4 16a8.6 8.6 0 0 1-.3-8.6l5.5 3.2\"/><path d=\"m14 12.5 5.6 3.5a8.6 8.6 0 0 1-7.4 4.3l-2.6-5.5\"/></symbol>\n    <symbol id=\"i-tower\" viewBox=\"0 0 24 24\"><path d=\"M12 21V9\"/><path d=\"m12 9-3.4-5M12 9l3.4-5\"/><path d=\"M8 21h8\"/><path d=\"M6 6.5a7 7 0 0 1 12 0\"/></symbol>\n    <symbol id=\"i-cable\" viewBox=\"0 0 24 24\"><path d=\"M2 8c4 0 4 8 8 8s4-8 8-8 4 8 4 8\"/><circle cx=\"2\" cy=\"8\" r=\"1.4\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"22\" cy=\"16\" r=\"1.4\" fill=\"currentColor\" stroke=\"none\"/></symbol>\n    <symbol id=\"i-bug\" viewBox=\"0 0 24 24\"><rect x=\"8\" y=\"8\" width=\"8\" height=\"12\" rx=\"4\"/><path d=\"M8 12H4M16 12h4M8.5 8.5 5 6M15.5 8.5 19 6M8.5 17 5.5 19.5M15.5 17l3 2.5\"/><path d=\"M9.5 8V6.5a2.5 2.5 0 0 1 5 0V8\"/></symbol>\n    <symbol id=\"i-shield\" viewBox=\"0 0 24 24\"><path d=\"M12 3 5 6v6c0 4.2 3 7.6 7 9 4-1.4 7-4.8 7-9V6l-7-3Z\"/><path d=\"m9 12 2.2 2.2L15.5 10\"/></symbol>\n    <symbol id=\"i-user\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8.5\" r=\"3.8\"/><path d=\"M4.5 20.5c.8-3.8 3.8-6 7.5-6s6.7 2.2 7.5 6\"/></symbol>\n    <symbol id=\"i-mail\" viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5.5\" width=\"18\" height=\"13\" rx=\"2.4\"/><path d=\"m3.8 7.2 8.2 6 8.2-6\"/></symbol>\n    <symbol id=\"i-at\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M16 8v5a2.6 2.6 0 0 0 5 1V12a9 9 0 1 0-3.6 7.2\"/></symbol>\n    <symbol id=\"i-phone\" viewBox=\"0 0 24 24\"><rect x=\"7\" y=\"2.6\" width=\"10\" height=\"18.8\" rx=\"2.6\"/><path d=\"M10.6 5.2h2.8\"/><circle cx=\"12\" cy=\"18.2\" r=\".9\" fill=\"currentColor\" stroke=\"none\"/></symbol>\n    <symbol id=\"i-pin\" viewBox=\"0 0 24 24\"><path d=\"M12 21s6.4-6.1 6.4-10.6A6.4 6.4 0 0 0 5.6 10.4C5.6 14.9 12 21 12 21Z\"/><circle cx=\"12\" cy=\"10.3\" r=\"2.4\"/></symbol>\n    <symbol id=\"i-cross\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"6.5\"/><path d=\"M12 1.8v3.6M12 18.6v3.6M1.8 12h3.6M18.6 12h3.6\"/></symbol>\n    <symbol id=\"i-radar\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8.6\"/><circle cx=\"12\" cy=\"12\" r=\"4.4\"/><path d=\"M12 12 18 6\"/><circle cx=\"12\" cy=\"12\" r=\"1.3\" fill=\"currentColor\" stroke=\"none\"/></symbol>\n    <symbol id=\"i-pen\" viewBox=\"0 0 24 24\"><path d=\"m4 16.6 9.6-9.6 3.4 3.4-9.6 9.6L4 20l.1-3.4Z\"/><path d=\"m13.6 7 2.2-2.2a1.6 1.6 0 0 1 2.3 0l1.1 1.1a1.6 1.6 0 0 1 0 2.3L17 10.4\"/></symbol>\n    <symbol id=\"i-route\" viewBox=\"0 0 24 24\"><circle cx=\"5.5\" cy=\"5.5\" r=\"2.5\"/><circle cx=\"18.5\" cy=\"18.5\" r=\"2.5\"/><path d=\"M8 5.5h5.4a3.4 3.4 0 0 1 0 6.8H9.9a3.4 3.4 0 0 0 0 6.8H16\"/></symbol>\n    <symbol id=\"i-settings\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 14.4a1.6 1.6 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.6 1.6 0 0 0-2.7 1.1v.4a2 2 0 1 1-4 0v-.2a1.6 1.6 0 0 0-2.8-1.1l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.6 1.6 0 0 0-1.1-2.7H3.4a2 2 0 1 1 0-4h.2a1.6 1.6 0 0 0 1.1-2.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.6 1.6 0 0 0 2.7-1.1V3.4a2 2 0 1 1 4 0v.2a1.6 1.6 0 0 0 2.7 1.1l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.6 1.6 0 0 0 1.1 2.7h.4a2 2 0 1 1 0 4h-.2a1.6 1.6 0 0 0-1.4 1.1Z\"/></symbol>\n    <symbol id=\"i-share\" viewBox=\"0 0 24 24\"><circle cx=\"18\" cy=\"5.5\" r=\"2.6\"/><circle cx=\"6\" cy=\"12\" r=\"2.6\"/><circle cx=\"18\" cy=\"18.5\" r=\"2.6\"/><path d=\"m8.3 10.7 7.4-3.9M8.3 13.3l7.4 3.9\"/></symbol>\n    <symbol id=\"i-eye\" viewBox=\"0 0 24 24\"><path d=\"M2 12s3.6-6.4 10-6.4S22 12 22 12s-3.6 6.4-10 6.4S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"2.8\"/></symbol>\n    <symbol id=\"i-close\" viewBox=\"0 0 24 24\"><path d=\"m6 6 12 12M18 6 6 18\"/></symbol>\n    <symbol id=\"i-menu\" viewBox=\"0 0 24 24\"><path d=\"M3.5 7h17M3.5 12h17M3.5 17h17\"/></symbol>\n    <symbol id=\"i-spark\" viewBox=\"0 0 24 24\"><path d=\"M12 3.2l1.85 5.05L19 10.1l-5.15 1.85L12 17l-1.85-5.05L5 10.1l5.15-1.85Z\"/><path d=\"M18.5 16.2l.85 2.3 2.3.85-2.3.85-.85 2.3-.85-2.3-2.3-.85 2.3-.85Z\"/></symbol>\n    <symbol id=\"i-send\" viewBox=\"0 0 24 24\"><path d=\"M21 3 10.6 13.4\"/><path d=\"M21 3l-6.4 18-4-9-9-4Z\"/></symbol>\n    <symbol id=\"i-plus\" viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></symbol>\n    <symbol id=\"i-key\" viewBox=\"0 0 24 24\"><circle cx=\"7.5\" cy=\"15.5\" r=\"3.6\"/><path d=\"M10.2 12.8 19 4M16.4 6.6l2.4 2.4M14 9l2.4 2.4\"/></symbol>\n    <symbol id=\"i-download\" viewBox=\"0 0 24 24\"><path d=\"M12 3.5v11\"/><path d=\"m7.5 10.5 4.5 4.5 4.5-4.5\"/><path d=\"M4.5 19.5h15\"/></symbol>\n    <symbol id=\"i-sat-on\" viewBox=\"0 0 24 24\"><path d=\"M6 4.5 4.5 6l2.4 2.4L5.4 10 3 7.6 4.5 6 6 4.5Z\"/><path d=\"m14.5 5.5 4 4\"/><path d=\"M11 9 9 11l4 4 2-2\"/><circle cx=\"15.5\" cy=\"15.5\" r=\"4\"/><path d=\"m18.3 18.3 2.2 2.2\"/></symbol>\n  </defs>\n</svg>\n\n<div class=\"app\" id=\"app\">\n\n  <!-- ── HEADER ─────────────────────────────────────────── -->\n  <header class=\"hdr\">\n    <a class=\"logo\" href=\"#\" aria-label=\"Badr\">\n      <svg class=\"ic lg\"><use href=\"#i-logo\"/></svg>\n    </a>\n    <div class=\"title-wrap\">\n      <div class=\"title\">BADR <b>LIVE EARTH</b></div>\n      <span class=\"sub\">GLOBAL INTELLIGENCE · v5</span>\n    </div>\n    <div class=\"maps\" role=\"group\" aria-label=\"Map view\">\n      <button class=\"btn icon on locked\" id=\"btn2d\" title=\"2D flat map — locked, no 3D\" aria-pressed=\"true\"><svg class=\"ic\"><use href=\"#i-flat\"/></svg><span class=\"lbl-txt\">2D</span></button>\n      <button class=\"btn icon on\" id=\"btnLayers\" title=\"Layers\" aria-pressed=\"true\"><svg class=\"ic\"><use href=\"#i-layers\"/></svg></button>\n      <button class=\"btn icon off\" id=\"btnSearch\" title=\"Search\" aria-pressed=\"false\"><svg class=\"ic\"><use href=\"#i-search\"/></svg></button>\n      <button class=\"btn icon off\" id=\"btnFull\" title=\"Full screen\" aria-pressed=\"false\"><svg class=\"ic\"><use href=\"#i-expand\"/></svg></button>\n    </div>\n    <button class=\"btn alert alertpill\" id=\"btnAlerts\" title=\"Alerts — always on, cannot be turned off\"><svg class=\"ic sm\"><use href=\"#i-alert\"/></svg><span class=\"ap-t\">Alerts</span><span class=\"count\">12</span></button>\n  </header>\n\n  <!-- ── ALERT STRIP (always on) ─────────────────────────── -->\n  <div class=\"alertbar\">\n    <span class=\"lbl\"><svg class=\"ic sm\"><use href=\"#i-alert\"/></svg>Live</span>\n    <span class=\"txt\">4 new seismic events · 1 aviation alert · 2 cyber incidents · radiation nominal</span>\n    <span class=\"more\">VIEW</span>\n  </div>\n\n  <!-- ── LEFT RAIL ───────────────────────────────────────── -->\n  <nav class=\"rail\" id=\"rail\">\n    <button class=\"rbtn on\" data-on=\"1\"><svg class=\"ic\"><use href=\"#i-sat\"/></svg><span class=\"tip\">Satellites</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-plane\"/></svg><span class=\"tip\">Aircraft</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-ship\"/></svg><span class=\"tip\">Maritime</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-balloon\"/></svg><span class=\"tip\">Balloons</span></button>\n    <div class=\"sep\"></div>\n    <button class=\"rbtn on\" data-on=\"1\"><svg class=\"ic\"><use href=\"#i-cctv\"/></svg><span class=\"tip\">CCTV</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-fire\"/></svg><span class=\"tip\">Fires</span></button>\n    <button class=\"rbtn on\" data-on=\"1\"><svg class=\"ic\"><use href=\"#i-quake\"/></svg><span class=\"tip\">Seismic</span></button>\n    <button class=\"rbtn err\" data-on=\"err\"><svg class=\"ic\"><use href=\"#i-rad\"/></svg><span class=\"tip\">Radiation · source down</span></button>\n    <div class=\"sep\"></div>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-tower\"/></svg><span class=\"tip\">Infrastructure</span></button>\n    <button class=\"rbtn on\" data-on=\"1\"><svg class=\"ic\"><use href=\"#i-cable\"/></svg><span class=\"tip\">Submarine cables</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-bug\"/></svg><span class=\"tip\">Malware</span></button>\n    <button class=\"rbtn on\" data-on=\"1\"><svg class=\"ic\"><use href=\"#i-shield\"/></svg><span class=\"tip\">Cyber</span></button>\n    <div class=\"sep\"></div>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-pen\"/></svg><span class=\"tip\">Draw</span></button>\n    <button class=\"rbtn\" data-on=\"0\"><svg class=\"ic\"><use href=\"#i-route\"/></svg><span class=\"tip\">Route</span></button>\n    <div class=\"grow\"></div>\n    <button class=\"rbtn\"><svg class=\"ic\"><use href=\"#i-settings\"/></svg><span class=\"tip\">Settings</span></button>\n  </nav>\n\n  <!-- ── MAP ─────────────────────────────────────────────── -->\n  <main class=\"stage\">\n    <div class=\"grid-lines\"></div>\n    <div class=\"plane-ghost\"></div>\n    <div class=\"mapctl\">\n      <button class=\"btn on\" id=\"masterSat\"><svg class=\"ic sm\"><use href=\"#i-sat\"/></svg> All sats <span class=\"count\" id=\"satCount\">8/8</span></button>\n      <button class=\"btn off\" id=\"masterAir\"><svg class=\"ic sm\"><use href=\"#i-plane\"/></svg> All planes</button>\n      <button class=\"btn err\" id=\"masterRad\"><svg class=\"ic sm\"><use href=\"#i-rad\"/></svg> Radiation <span class=\"count\">!</span></button>\n    </div>\n    <div class=\"stamp\">2D flat · equirectangular · 62.4°N 14.2°E · zoom 4</div>\n  </main>\n\n  <!-- ── RIGHT: OSINT TOOLKIT ────────────────────────────── -->\n  <aside class=\"side\" id=\"side\">\n    <div class=\"side-h\">\n      <svg class=\"ic sm\" style=\"color:var(--gold)\"><use href=\"#i-radar\"/></svg>\n      <span class=\"t\">OSINT Toolkit</span>\n      <span class=\"n\">5 ENGINES</span>\n      <button class=\"sheet-x\" id=\"sideClose\"><svg class=\"ic sm\"><use href=\"#i-close\"/></svg></button>\n    </div>\n    <div class=\"side-b\">\n\n      <div class=\"card\">\n        <div class=\"card-h\"><svg class=\"ic\"><use href=\"#i-user\"/></svg><span class=\"t\">Username</span><span class=\"s\">40+ SITES</span></div>\n        <div class=\"tabs\">\n          <button class=\"tab on\">All</button><button class=\"tab\">Social</button><button class=\"tab\">Dev</button><button class=\"tab\">Adult</button>\n        </div>\n        <form class=\"field\">\n          <input placeholder=\"username\" value=\"badr\">\n          <button class=\"go\"><svg class=\"ic sm\"><use href=\"#i-search\"/></svg>Run</button>\n        </form>\n        <div class=\"res\">\n          <div class=\"res-i\"><b>github.com/badr</b><span class=\"st found\">FOUND</span></div>\n          <div class=\"res-i\"><b>x.com/badr</b><span class=\"st found\">FOUND</span></div>\n          <div class=\"res-i\"><b>reddit.com/u/badr</b><span class=\"st none\">NONE</span></div>\n          <div class=\"res-i\"><b>keybase.io/badr</b><span class=\"st warn\">CHECK</span></div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\"><svg class=\"ic\"><use href=\"#i-mail\"/></svg><span class=\"t\">Email</span><span class=\"s\">BREACH + MX</span></div>\n        <form class=\"field\">\n          <input placeholder=\"name@domain.com\">\n          <button class=\"go\"><svg class=\"ic sm\"><use href=\"#i-search\"/></svg>Run</button>\n        </form>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\"><svg class=\"ic\"><use href=\"#i-at\"/></svg><span class=\"t\">Domain</span><span class=\"s\">DNS · WHOIS</span></div>\n        <form class=\"field\">\n          <input placeholder=\"example.com\">\n          <button class=\"go\"><svg class=\"ic sm\"><use href=\"#i-search\"/></svg>Run</button>\n        </form>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\"><svg class=\"ic\"><use href=\"#i-pin\"/></svg><span class=\"t\">IP / Geo</span><span class=\"s\">ASN · REP</span></div>\n        <form class=\"field\">\n          <input placeholder=\"1.1.1.1\">\n          <button class=\"go\"><svg class=\"ic sm\"><use href=\"#i-search\"/></svg>Run</button>\n        </form>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\"><svg class=\"ic\"><use href=\"#i-phone\"/></svg><span class=\"t\">Phone</span><span class=\"s\">CARRIER</span></div>\n        <form class=\"field\">\n          <input placeholder=\"+20 ...\">\n          <button class=\"go\"><svg class=\"ic sm\"><use href=\"#i-search\"/></svg>Run</button>\n        </form>\n      </div>\n\n    </div>\n  </aside>\n\n\n  <!-- ── SCRIM (mobile sheet + assist) ───────────────────── -->\n  <div class=\"scrim\" id=\"scrim\"></div>\n\n  <!-- ── BADR ASSIST — free Cloudflare models, many providers ── -->\n  <section class=\"ai\" id=\"ai\" aria-hidden=\"true\" aria-label=\"Badr Assist\">\n    <header class=\"ai-h\">\n      <svg class=\"ic sm ai-mark\"><use href=\"#i-spark\"/></svg>\n      <span class=\"t\">Badr Assist</span>\n      <span class=\"ai-st\" id=\"aiState\" title=\"connection state\"><i class=\"dot\"></i><span id=\"aiStateTxt\">not connected</span></span>\n      <button class=\"ai-x\" id=\"btnAiCfg\" title=\"Connection settings\" aria-label=\"Connection settings\"><svg class=\"ic sm\"><use href=\"#i-key\"/></svg></button>\n      <button class=\"ai-x\" id=\"btnAiClose\" title=\"Close\" aria-label=\"Close\"><svg class=\"ic sm\"><use href=\"#i-close\"/></svg></button>\n    </header>\n\n    <div class=\"ai-cfg\" id=\"aiCfg\" hidden>\n      <label class=\"cfg-row\"><span class=\"cfg-lbl\">Model</span>\n        <select id=\"aiModel\"></select>\n      </label>\n\n      <label class=\"cfg-row\"><span class=\"cfg-lbl\">Endpt</span>\n        <input id=\"aiEndpoint\" spellcheck=\"false\" autocomplete=\"off\"\n               placeholder=\"https://your-worker.workers.dev\"></label>\n\n      <div class=\"cfg-row\">\n        <span class=\"cfg-lbl\">Key</span>\n        <input id=\"aiKey\" type=\"password\" spellcheck=\"false\" autocomplete=\"off\"\n               placeholder=\"optional — only if your worker sets BADR_KEY\">\n        <button class=\"go-sm\" id=\"btnTest\" type=\"button\">Test</button>\n      </div>\n\n      <p class=\"cfg-note\" id=\"aiNote\">Not connected yet. Deploy the tiny worker once, then paste its\naddress above and press Test. No API key and no account id are ever typed into this page.</p>\n    </div>\n\n    <div class=\"ai-log\" id=\"aiLog\">\n      <div class=\"ai-msg sys\">Badr Assist. Six free models — Llama 3.3, Llama 3.1, Qwen Coder, DeepSeek R1,\nMistral and GPT-OSS. Pick a model, set one address, done.</div>\n    </div>\n\n    <form class=\"ai-in\" id=\"aiForm\" autocomplete=\"off\">\n      <input id=\"aiInput\" placeholder=\"Ask about the map, a layer, a tool…\" spellcheck=\"false\">\n      <button class=\"go\" type=\"submit\" aria-label=\"Send\"><svg class=\"ic sm\"><use href=\"#i-send\"/></svg></button>\n    </form>\n  </section>\n\n  <!-- ── BOTTOM DOCK ─────────────────────────────────────── -->\n  <footer class=\"dock\">\n    <div class=\"dock-scroll\">\n      <button class=\"slot used\"><svg class=\"ic sm\"><use href=\"#i-download\"/></svg><span class=\"slot-t\">Export</span></button>\n      <button class=\"slot used\"><svg class=\"ic sm\"><use href=\"#i-share\"/></svg><span class=\"slot-t\">Share view</span></button>\n      <button class=\"slot free\"><svg class=\"ic sm\"><use href=\"#i-plus\"/></svg><span class=\"slot-t\">Slot 3</span></button>\n      <button class=\"slot free\"><svg class=\"ic sm\"><use href=\"#i-plus\"/></svg><span class=\"slot-t\">Slot 4</span></button>\n      <button class=\"slot free\"><svg class=\"ic sm\"><use href=\"#i-plus\"/></svg><span class=\"slot-t\">Slot 5</span></button>\n    </div>\n    <div class=\"dock-pin\">\n      <button class=\"btn icon ai-trigger\" id=\"btnAi\" title=\"Badr Assist — free AI chat\" aria-expanded=\"false\"><svg class=\"ic\"><use href=\"#i-spark\"/></svg></button>\n      <button class=\"btn icon mobile-only\" id=\"btnSide\" title=\"OSINT toolkit\"><svg class=\"ic\"><use href=\"#i-radar\"/></svg></button>\n      <span class=\"clock\" id=\"clock\">00:00:00Z</span>\n    </div>\n  </footer>\n</div>\n\n<script>\n(function(){\n  \"use strict\";\n  var app = document.getElementById('app');\n\n  /* rail toggles: click cycles on → off → (err → off) */\n  document.querySelectorAll('.rbtn[data-on]').forEach(function(b){\n    b.addEventListener('click', function(){\n      if (b.dataset.on === 'err'){ b.classList.remove('err'); b.classList.add('on'); b.dataset.on='1'; return; }\n      var on = b.classList.toggle('on');\n      b.dataset.on = on ? '1' : '0';\n      if (on) b.classList.remove('err');\n    });\n  });\n\n  /* header buttons */\n  function toggle(el){ el.classList.toggle('on'); el.classList.toggle('off', !el.classList.contains('on')); }\n  ['btnLayers','btnSearch','btnFull'].forEach(function(id){\n    var b = document.getElementById(id);\n    if (b) b.addEventListener('click', function(){ toggle(b); });\n  });\n\n  /* 2D is locked: clicking it does nothing (there is no 3D mode) */\n  /* master switches */\n  var sats = document.getElementById('masterSat');\n  var n = 8;\n  sats.addEventListener('click', function(){\n    toggle(sats);\n    sats.classList.remove('err');\n    n = sats.classList.contains('on') ? 8 : 0;\n    document.getElementById('satCount').textContent = n + '/8';\n  });\n  var air = document.getElementById('masterAir');\n  air.addEventListener('click', function(){ toggle(air); air.classList.remove('err'); });\n\n  /* side sheet on mobile */\n  var side = document.getElementById('side');\n  document.getElementById('btnSide').addEventListener('click', function(){\n    app.classList.toggle('side-open');\n  });\n  document.getElementById('sideClose').addEventListener('click', function(){\n    app.classList.remove('side-open');\n  });\n\n  /* clock */\n  function tick(){\n    var d = new Date();\n    var p = function(x){ return String(x).padStart(2,'0'); };\n    document.getElementById('clock').textContent =\n      p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()) + ':' + p(d.getUTCSeconds()) + 'Z';\n  }\n  tick(); setInterval(tick, 1000);\n})();\n</script>\n<script>\n/* ══════════════════════════════════════════════════════════\n   BADR ASSIST — free Cloudflare Workers AI, several models\n\n   The page never holds a token. It talks to ONE address you own:\n       GET  <endpt>/api/models   → { models:[{id,label}], ok:true }\n       POST <endpt>/api/chat     → { reply }   body { messages, model }\n   Leave Endpt blank to use this page's own origin (/api/models).\n\n   Everything printed is real. There are no canned replies here.\n   ══════════════════════════════════════════════════════════ */\n(function(){\n  \"use strict\";\n\n  var K = { endpoint:\"badr.ai.ep\", model:\"badr.ai.model\", key:\"badr.ai.key\" };\n\n  var MODELS = [\n    { id:\"@cf/meta/llama-3.3-70b-instruct-fp8-fast\",        label:\"Llama 3.3 70B — best all-round\" },\n    { id:\"@cf/openai/gpt-oss-120b\",                          label:\"GPT-OSS 120B — OpenAI open model\" },\n    { id:\"@cf/qwen/qwen2.5-coder-32b-instruct\",              label:\"Qwen 2.5 Coder 32B — code\" },\n    { id:\"@cf/deepseek-ai/deepseek-r1-distill-qwen-32b\",     label:\"DeepSeek R1 32B — reasoning\" },\n    { id:\"@cf/mistralai/mistral-small-3.1-24b-instruct\",     label:\"Mistral Small 3.1 24B\" },\n    { id:\"@cf/meta/llama-3.1-8b-instruct\",                   label:\"Llama 3.1 8B — fastest\" }\n  ];\n\n  var SYS = \"You are Badr Assist, a terse helper inside the BADR LIVE EARTH geospatial dashboard. \" +\n            \"The map is 2D flat only; there is no 3D globe mode, so never suggest one. \" +\n            \"Answer in short plain sentences, no tables, no emoji, no invented numbers. \" +\n            \"If you do not know something, say so.\";\n\n  function $(id){ return document.getElementById(id); }\n  function get(k, d){ try { var v = localStorage.getItem(k); return v === null ? d : v; } catch(e){ return d; } }\n  function set(k, v){ try { localStorage.setItem(k, v); } catch(e){} }\n\n  var ai = $(\"ai\"), scrim = $(\"scrim\"), logEl = $(\"aiLog\"), form = $(\"aiForm\"), input = $(\"aiInput\");\n  var stateEl = $(\"aiState\"), stateTxt = $(\"aiStateTxt\"), goBtn = form.querySelector(\".go\");\n  var cfgBox = $(\"aiCfg\"), btnCfg = $(\"btnAiCfg\"), sel = $(\"aiModel\"), note = $(\"aiNote\");\n  var appEl = $(\"app\");\n\n  var cfg = {\n    endpoint: get(K.endpoint, \"\").replace(/\\/+$/, \"\"),\n    model:    get(K.model, MODELS[0].id),\n    key:      get(K.key, \"\")\n  };\n  var history = [];\n  var busy = false;\n  var live = false;      /* true only after the endpoint actually answered */\n\n  /* ── ui helpers ─────────────────────────────────────────── */\n  function chip(kind, txt){\n    stateEl.className = \"ai-st\" + (kind ? \" \" + kind : \"\");\n    stateTxt.textContent = txt;\n  }\n  function say(kind, text){\n    var d = document.createElement(\"div\");\n    d.className = \"ai-msg \" + kind;\n    d.textContent = text;\n    logEl.appendChild(d);\n    logEl.scrollTop = logEl.scrollHeight;\n    return d;\n  }\n  function fillModels(list){\n    var use = (list && list.length) ? list : MODELS;\n    sel.textContent = \"\";\n    use.forEach(function(m){\n      var o = document.createElement(\"option\");\n      o.value = m.id;\n      o.textContent = m.label || m.id;\n      sel.appendChild(o);\n    });\n    var has = use.some(function(m){ return m.id === cfg.model; });\n    sel.value = has ? cfg.model : use[0].id;\n    cfg.model = sel.value;\n  }\n\n  /* ── address ────────────────────────────────────────────── */\n  function url(path){ return cfg.endpoint + path; }\n  function headers(json){\n    var h = json ? { \"content-type\":\"application/json\" } : {};\n    if (cfg.key) h[\"x-badr-key\"] = cfg.key;\n    return h;\n  }\n  function explain(err, target){\n    var m = (err && err.message) ? err.message : String(err);\n    if (/failed to fetch|networkerror|load failed/i.test(m)){\n      return \"The browser blocked the call to \" + target + \" before it left the page.\\n\" +\n             \"That means the address did not answer with an Access-Control-Allow-Origin header. \" +\n             \"The supplied worker sends it; a plain API endpoint does not. \" +\n             \"Open \" + target + \" in a normal tab — if it answers there and not here, it is CORS, not the model.\";\n    }\n    return m;\n  }\n  function readJson(res){\n    return res.text().then(function(txt){\n      var j = null;\n      try { j = JSON.parse(txt); } catch(e){}\n      return { status: res.status, ok: res.ok, json: j, text: txt };\n    });\n  }\n\n  /* ── test the endpoint ──────────────────────────────────── */\n  function test(silent){\n    /* only trust the input when the drawer is actually showing it,\n       otherwise a boot-time test would wipe the saved address */\n    if (!cfgBox.hasAttribute(\"hidden\")){\n      cfg.endpoint = $(\"aiEndpoint\").value.trim().replace(/\\/+$/, \"\");\n      set(K.endpoint, cfg.endpoint);\n    }\n    var target = url(\"/api/models\");\n\n    if (typeof fetch !== \"function\"){\n      chip(\"err\", \"no fetch\");\n      note.textContent = \"This browser has no fetch().\";\n      return Promise.resolve(false);\n    }\n    chip(\"work\", \"testing…\");\n    return fetch(target, { headers: headers(false) })\n      .then(readJson)\n      .then(function(r){\n        if (!r.ok){\n          live = false;\n          chip(\"err\", \"HTTP \" + r.status);\n          note.textContent = \"The address answered HTTP \" + r.status + \" at \" + target + \".\\n\" +\n            ((r.json && (r.json.error || r.json.detail)) || r.text.slice(0, 200)) +\n            \"\\nCheck it is the worker root, with no /api on the end.\";\n          if (!silent) say(\"bad\", note.textContent);\n          return false;\n        }\n        live = true;\n        if (r.json && Array.isArray(r.json.models) && r.json.models.length) fillModels(r.json.models);\n        var n = sel.options.length;\n        chip(\"on\", \"ready · \" + n + \" models\");\n        note.textContent = \"Connected to \" + (cfg.endpoint || location.origin) + \"\\n\" +\n          n + \" models available\" + (cfg.key ? \" · key sent\" : \" · no key\") +\n          \". Pick a model above, then just type below.\";\n        if (!silent) say(\"sys\", \"Connected. \" + n + \" models available. Nothing was invented to say this.\");\n        return true;\n      })\n      .catch(function(err){\n        live = false;\n        chip(\"err\", \"no answer\");\n        note.textContent = explain(err, target);\n        if (!silent) say(\"bad\", note.textContent);\n        return false;\n      });\n  }\n\n  /* ── send ───────────────────────────────────────────────── */\n  form.addEventListener(\"submit\", function(e){\n    e.preventDefault();\n    var q = input.value.trim();\n    if (!q || busy) return;\n\n    /* A page opened from disk has no server of its own. Saying \"CORS\" here\n       would be a lie: there is simply nothing at that address to call. */\n    if (!cfg.endpoint && location.protocol === \"file:\"){\n      say(\"bad\",\n        \"Nothing was sent, because this page has no server to talk to.\\n\\n\" +\n        \"This file was opened from your disk. On its own it is only a skin — it cannot reach any AI.\\n\\n\" +\n        \"Two ways to give it one:\\n\" +\n        \"1) Deploy badr-ai-app.js as a Cloudflare Worker. That single file serves this exact page AND the \" +\n        \"AI together, so there is nothing to configure — just open the address it gives you.\\n\" +\n        \"2) Deploy badr-assist-worker.js, then paste its address into the key drawer and press Test.\");\n      openAi(true);\n      return;\n    }\n\n    input.value = \"\";\n    say(\"me\", q);\n    history.push({ role:\"user\", content:q });\n\n    var target = url(\"/api/chat\");\n    var think = say(\"think\", \"asking \" + (cfg.model.split(\"/\").pop() || cfg.model) + \" at \" + (cfg.endpoint || location.origin) + \" …\");\n    busy = true; goBtn.disabled = true; chip(\"work\", \"thinking\");\n\n    var messages = [{ role:\"system\", content:SYS }].concat(history.slice(-10));\n\n    fetch(target, {\n      method: \"POST\",\n      headers: headers(true),\n      body: JSON.stringify({ messages: messages, model: cfg.model, message: q })\n    })\n    .then(readJson)\n    .then(function(r){\n      if (!r.ok){\n        var why = (r.json && (r.json.error || r.json.detail)) || r.text.slice(0, 300);\n        throw new Error(\"HTTP \" + r.status + \" — \" + why);\n      }\n      var j = r.json;\n      var out = (j && (j.reply || j.response || j.text || j.content))\n             || (j && j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content)\n             || (j && j.result && j.result.response);\n      if (typeof out !== \"string\" || !out.trim()){\n        throw new Error(\"the server answered \" + r.status + \" but with no reply field. Raw: \" + r.text.slice(0, 240));\n      }\n      return out.trim();\n    })\n    .then(function(reply){\n      think.remove();\n      say(\"bot\", reply);\n      history.push({ role:\"assistant\", content:reply });\n      chip(\"on\", \"ready · \" + sel.options.length + \" models\");\n    })\n    .catch(function(err){\n      think.remove();\n      say(\"bad\", \"That did not go through.\\n\" + explain(err, target));\n      chip(\"err\", \"failed\");\n      history.pop();\n      if (!cfg.endpoint) say(\"sys\", \"No endpoint set. Open the key icon and paste your worker address.\");\n    })\n    .then(function(){\n      busy = false; goBtn.disabled = false;\n    });\n  });\n\n  /* ── drawer ─────────────────────────────────────────────── */\n  btnCfg.addEventListener(\"click\", function(){\n    var opening = cfgBox.hasAttribute(\"hidden\");\n    if (opening){\n      cfgBox.removeAttribute(\"hidden\");\n      btnCfg.classList.add(\"on\");\n      $(\"aiEndpoint\").value = cfg.endpoint;\n      $(\"aiKey\").value = cfg.key;\n      fillModels(null);\n    } else {\n      cfgBox.setAttribute(\"hidden\", \"\");\n      btnCfg.classList.remove(\"on\");\n    }\n  });\n\n  $(\"aiEndpoint\").addEventListener(\"input\", function(){\n    cfg.endpoint = this.value.trim().replace(/\\/+$/, \"\");\n    set(K.endpoint, cfg.endpoint);\n  });\n  $(\"aiKey\").addEventListener(\"input\", function(){\n    cfg.key = this.value.trim();\n    set(K.key, cfg.key);\n  });\n  sel.addEventListener(\"change\", function(){\n    cfg.model = this.value;\n    set(K.model, cfg.model);\n  });\n  $(\"btnTest\").addEventListener(\"click\", function(){ test(false); });\n  $(\"aiEndpoint\").addEventListener(\"keydown\", function(e){\n    if (e.key === \"Enter\"){ e.preventDefault(); test(false); }\n  });\n\n  /* ── open / close ───────────────────────────────────────── */\n  function isMobile(){\n    return window.matchMedia ? window.matchMedia(\"(max-width:820px)\").matches : window.innerWidth <= 820;\n  }\n  function syncScrim(){\n    var mobile = isMobile();\n    scrim.classList.toggle(\"on\",\n      (ai.classList.contains(\"open\") && mobile) || (appEl.classList.contains(\"side-open\") && mobile));\n  }\n  function openAi(v){\n    ai.classList.toggle(\"open\", v);\n    ai.setAttribute(\"aria-hidden\", v ? \"false\" : \"true\");\n    $(\"btnAi\").classList.toggle(\"on\", v);\n    $(\"btnAi\").setAttribute(\"aria-expanded\", v ? \"true\" : \"false\");\n    syncScrim();\n    if (v){\n      setTimeout(function(){ input.focus(); }, 70);\n      if (cfg.endpoint && !live) test(true);\n    }\n  }\n\n  $(\"btnAi\").addEventListener(\"click\", function(){ openAi(!ai.classList.contains(\"open\")); });\n  $(\"btnAiClose\").addEventListener(\"click\", function(){ openAi(false); });\n  $(\"sideClose\").addEventListener(\"click\", function(){ appEl.classList.remove(\"side-open\"); syncScrim(); });\n  $(\"btnSide\").addEventListener(\"click\", function(){ setTimeout(syncScrim, 0); });\n  scrim.addEventListener(\"click\", function(){\n    openAi(false); appEl.classList.remove(\"side-open\"); syncScrim();\n  });\n  document.addEventListener(\"keydown\", function(e){\n    if (e.key === \"Escape\"){ openAi(false); appEl.classList.remove(\"side-open\"); syncScrim(); }\n  });\n  window.addEventListener(\"resize\", syncScrim);\n\n  /* ── OSINT cards are still a skin: stop them reloading the page ── */\n  [].forEach.call(document.querySelectorAll(\"form.field\"), function(f){\n    f.addEventListener(\"submit\", function(e){\n      e.preventDefault();\n      var card = f.closest(\".card\");\n      var tt = card ? card.querySelector(\".card-h .t\") : null;\n      say(\"sys\", (tt ? tt.textContent : \"This tool\") +\n        \": still a skin — it calls no live API yet. Nothing was sent.\");\n      openAi(true);\n    });\n  });\n\n  /* ── boot ───────────────────────────────────────────────── */\n  fillModels(null);\n  syncScrim();\n\n  if (cfg.endpoint){\n    chip(\"\", \"not connected\");\n    test(true);\n  } else if (location.protocol === \"file:\"){\n    chip(\"err\", \"no endpoint\");\n    say(\"sys\",\n      \"Opened from disk — no server here, so no AI either.\\n\" +\n      \"Deploy badr-ai-app.js (one file, serves this page and the AI together) and open its address, \" +\n      \"or deploy badr-assist-worker.js and paste its address in the key drawer.\");\n  } else {\n    /* served over http(s): the page may well be sitting on a worker that\n       already has /api/models, so ask it instead of guessing */\n    chip(\"work\", \"checking…\");\n    test(true).then(function(ok){\n      if (!ok) say(\"sys\", \"This page is being served without an AI backend. \" +\n        \"Deploy badr-ai-app.js to get both in one place.\");\n    });\n  }\n})();\n</script>\n\n</body>\n</html>\n";

const MODELS = [
  { id: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',     label: 'Llama 3.3 70B - best all-round' },
  { id: '@cf/openai/gpt-oss-120b',                      label: 'GPT-OSS 120B - OpenAI open model' },
  { id: '@cf/qwen/qwen2.5-coder-32b-instruct',          label: 'Qwen 2.5 Coder 32B - code' },
  { id: '@cf/deepseek-ai/deepseek-r1-distill-qwen-32b', label: 'DeepSeek R1 32B - reasoning' },
  { id: '@cf/mistralai/mistral-small-3.1-24b-instruct', label: 'Mistral Small 3.1 24B' },
  { id: '@cf/meta/llama-3.1-8b-instruct',               label: 'Llama 3.1 8B - fastest' },
];

const DEFAULT_MODEL = MODELS[0].id;
const MAX_MESSAGES = 12;
const MAX_CHARS = 4000;

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'content-type, x-badr-key',
  'Access-Control-Max-Age': '86400',
};

function json(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS, 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
  });
}

function cleanMessages(raw) {
  if (!Array.isArray(raw)) return [];
  return raw
    .slice(-MAX_MESSAGES)
    .map((m) => {
      const o = m && typeof m === 'object' ? m : {};
      const role = o.role === 'assistant' || o.role === 'system' ? o.role : 'user';
      const content = typeof o.content === 'string' ? o.content.slice(0, MAX_CHARS) : '';
      return { role, content };
    })
    .filter((m) => m.content.length > 0);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });

    // ── the panel itself ────────────────────────────────────────────────
    if (url.pathname === '/' || url.pathname === '/index.html' || url.pathname === '/panel') {
      return new Response(PANEL, {
        headers: {
          'content-type': 'text/html; charset=utf-8',
          'cache-control': 'no-store',
          'x-frame-options': 'SAMEORIGIN',
        },
      });
    }

    const backend = env.AI ? 'binding' : env.CF_AI_TOKEN ? 'rest' : 'none';

    if (url.pathname === '/api/health') {
      return json({ ok: true, backend, models: MODELS.length, default: DEFAULT_MODEL,
                    key: env.BADR_KEY ? 'required' : 'off' });
    }

    if (url.pathname === '/api/models') {
      return json({ models: MODELS, backend });
    }

    if (url.pathname !== '/api/chat') {
      return json({ error: 'Not found. GET / is the panel, POST /api/chat is the AI.' }, 404);
    }

    if (request.method !== 'POST') return json({ error: 'Use POST.' }, 405);

    if (env.BADR_KEY) {
      const sent = request.headers.get('x-badr-key') || url.searchParams.get('key');
      if (sent !== env.BADR_KEY) return json({ error: 'Bad or missing x-badr-key header.' }, 401);
    }

    let body;
    try {
      body = await request.json();
    } catch {
      return json({ error: 'Body was not valid JSON.' }, 400);
    }

    let messages = cleanMessages(body && body.messages);
    if (messages.length === 0 && body && typeof body.message === 'string' && body.message.trim()) {
      messages = [{ role: 'user', content: body.message.slice(0, MAX_CHARS) }];
    }
    if (messages.length === 0) {
      return json({ error: 'No messages. Send { messages:[...] } or { message:"..." }.' }, 400);
    }

    const asked = typeof (body && body.model) === 'string' ? body.model : '';
    const model = MODELS.some((m) => m.id === asked) ? asked : DEFAULT_MODEL;
    const started = Date.now();

    // ── 1st choice: Workers AI binding (no token at all) ────────────────
    if (env.AI) {
      try {
        const out = await env.AI.run(model, { messages, max_tokens: 512, temperature: 0.3 });
        const reply =
          (out && (out.response || out.result?.response || out.choices?.[0]?.message?.content)) || '';
        if (!String(reply).trim()) {
          return json({ error: 'The model returned an empty reply.', model, backend, raw: out }, 502);
        }
        return json({ reply: String(reply).trim(), model, backend, ms: Date.now() - started });
      } catch (err) {
        return json(
          { error: 'Workers AI binding failed: ' + (err && err.message ? err.message : String(err)),
            model, backend },
          502,
        );
      }
    }

    // ── 2nd choice: REST with a token ───────────────────────────────────
    const account = env.CF_ACCOUNT_ID;
    const token = env.CF_AI_TOKEN;
    if (!account || !token) {
      return json(
        { error: 'No AI configured. Add a Workers AI binding named AI (Settings -> Bindings).',
          backend: 'none' },
        503,
      );
    }

    let res;
    try {
      res = await fetch(
        `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(account)}/ai/v1/chat/completions`,
        {
          method: 'POST',
          headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
          body: JSON.stringify({ model, messages, stream: false, max_tokens: 512, temperature: 0.3 }),
        },
      );
    } catch (err) {
      return json({ error: 'Network: ' + (err && err.message ? err.message : String(err)), model }, 502);
    }

    const text = await res.text();
    if (!res.ok) return json({ error: 'Cloudflare said ' + res.status, detail: text.slice(0, 500), model }, res.status);

    let data;
    try {
      data = JSON.parse(text);
    } catch {
      return json({ error: 'Cloudflare returned non-JSON.', detail: text.slice(0, 400), model }, 502);
    }

    const reply = data?.choices?.[0]?.message?.content || data?.result?.response || '';
    if (!String(reply).trim()) return json({ error: 'Empty reply.', detail: text.slice(0, 400), model }, 502);

    return json({ reply: String(reply).trim(), model, backend, ms: Date.now() - started });
  },
};
